# owner: platform
from typing import Iterable, List
from rosterkit.models import Student
from operator import attrgetter


def _row_text(number: int, row: List[Student]) -> str:
    names = [student.display_name for student in row]
    return f"Row {number}: {' | '.join(names)}"


def _seating_rows(
    ordered: List[Student], seats: int
) -> List[str]:
    starts = range(0, len(ordered), seats)
    rows = [ordered[i : i + seats] for i in starts]
    numbered = enumerate(rows, 1)
    return [_row_text(n, row) for n, row in numbered]


# ---
def seating_chart(
    students: Iterable[Student], seats_per_row: int
) -> List[str]:
    """One line per row, sorted by last name."""
    ordered = sorted(students, key=attrgetter("last_name"))
    if seats_per_row <= 0 or not ordered:
        raise ValueError("need positive seats and students")
    return _seating_rows(ordered, seats_per_row)
